import java.util.Scanner

fun printDigit(d: Int) {
    var digit = d
    if (digit >= 5) {
        print("-O|")
    } else {
        print("O-|")
    }
    digit %= 5
    repeat(digit) { print("O") }
    print("-")
    repeat(4 - digit) { print("O") }
    println()
}

fun main() {
    val scanner = Scanner(System.`in`)
    var n = scanner.nextInt()

    printDigit(n % 10)
    n /= 10

    while (n > 0) {
        printDigit(n % 10)
        n /= 10
    }
}

